import pytest
from utils.paginate import paginate, total_pages, page_count_for

def test_paginate_basic():
    items = list(range(10))
    assert paginate(items, 0, 3) == [0, 1, 2]

def test_total_pages_exact():
    assert total_pages(list(range(9)), 3) == 3

def test_total_pages_partial():
    assert total_pages(list(range(10)), 3) == 4

